<body>
<div class="container">
  <table role="table" aria-label="销售排行榜">
    <caption>2026年Q1-Q3销售排行榜</caption>
    <thead>
      <tr>
        <th scope="col">排名</th>
        <th scope="col">姓名</th>
        <th scope="col">Q1业绩</th>
        <th scope="col">Q2业绩</th>
        <th scope="col">Q3业绩</th>
        <th scope="col">总分</th>
      </tr>
    </thead>
    <tbody id="table-body">
    </tbody>
  </table>
</div>
<script>
  (function() {
    // 原始数据
    const rawData = [
      ["赵磊",182,165,201],
      ["林晓雪",210,198,176],
      ["陈建国",145,189,212],
      ["王芳",195,171,195],
      ["张明",210,198,176],
      ["刘华",130,155,142],
      ["孙文博",178,193,190],
      ["周婷",168,183,167]
    ];

    // 计算总分并构建对象数组
    const data = rawData.map(([name, q1, q2, q3]) => ({
      name,
      q1,
      q2,
      q3,
      total: q1 + q2 + q3
    }));

    // 按总分降序排序
    data.sort((a, b) => b.total - a.total);

    // 排名处理：同分并列，跳号
    let rank = 1;
    let prevTotal = null;
    let actualIndex = 0;
    const rankedData = data.map((item, index) => {
      if (prevTotal !== null && item.total !== prevTotal) {
        rank = index + 1; // 跳号：下一档使用当前索引+1作为新排名
      }
      prevTotal = item.total;
      return { ...item, rank };
    });

    // 生成表格行
    const tbody = document.getElementById('table-body');
    rankedData.forEach(item => {
      const tr = document.createElement('tr');
      tr.setAttribute('data-rank', item.rank);
      tr.setAttribute('data-total', item.total);

      tr.innerHTML = `
        <td class="rank-col">${item.rank}</td>
        <td class="name-col">${item.name}</td>
        <td>${item.q1}</td>
        <td>${item.q2}</td>
        <td>${item.q3}</td>
        <td class="total-col">${item.total}</td>
      `;
      tbody.appendChild(tr);
    });
  })();
</script>
</body>
</html>
